import numpy as np

def objects_by_left(grid):
    """Bounding boxes of connected-by-color objects, ordered by left column."""
    g = np.array(grid); out = []; seen = set()
    for i in range(g.shape[0]):
        for j in range(g.shape[1]):
            v = g[i, j]
            if v and v not in seen:
                seen.add(v)
                cells = np.argwhere(g == v)
                r0, c0 = cells.min(0); r1, c1 = cells.max(0)
                out.append((v, int(r0), int(c0), g[r0:r1+1, c0:c1+1].copy()))
    return sorted(out, key=lambda s: s[2])

def diagonal_stack(grid):
    """Stack objects left-to-right along the diagonal: object k's box at column k, each top one row below the previous box's top."""
    S = objects_by_left(grid)
    out = np.zeros_like(np.array(grid)); row = 0
    for k, (v, r0, c0, box) in enumerate(S):
        h, w = box.shape
        for i in range(h):
            for j in range(w):
                if box[i, j]:
                    out[row + i, k + j] = box[i, j]
        row += h - 1
    return out.tolist()

def transform(grid):
    return diagonal_stack(grid)
